  const PMC = { los: 12.9, met: 11.2, rivo: 28.5, zolp: 46, ritalina: 61, amox: 24.9, insu: 68, dipi: 9.5, vitc: 27.5, coza: 98.9, amoxil: 52, ibup: 19.9 }, GIRO = { vitc: 75, zolp: 64, coza: 70, amoxil: 90 };
  prods.forEach((p) => { p.pmc = PMC[p.id] || null; p.ultVenda = GIRO[p.id] ?? 2; p.cat = p.id === 'vitc' ? 'Suplemento' : p.id === 'fral' ? 'Fralda e cuidado' : 'Medicamento'; }); prods.find((p) => p.id === 'los').ativo = 'losartana'; prods.find((p) => p.id === 'amox').ativo = 'amoxicilina';
