  const mes = String(new Date().getMonth() + 1).padStart(2, '0'), [cida, antonio, marcia, jorge] = clientes; cida.nasc = `${mes}-28`; marcia.nasc = `${mes}-09`; antonio.nasc = '03-15'; jorge.nasc = '12-02'; jorge.conv = 'cv1'; marcia.conv = 'cv2';
  const antes = (n) => new Date(Date.now() - n * 864e5).toLocaleDateString('pt-BR');
  const convenios = [{ id: 'cv1', nome: 'Metalúrgica Forte', desc: 10, faturas: [{ dia: antes(23), total: 412.8, n: 9, pago: true }] }, { id: 'cv2', nome: 'Prefeitura · servidores', desc: 8, faturas: [] }];
