const GRUPOS = [['Vender', [['caixa', 'Caixa', 'venda no balcão'], ['vendas', 'Vendas do dia', 'cupons e devolução'], ['fechamento', 'Fechar o caixa', 'sangria e conferência'], ['entregas', 'Entregas', 'pedidos do WhatsApp']]], ['Controle', [['controlados', 'Controlados', 'livro, balanço e SNGPC'], ['antibioticos', 'Antibióticos', 'receitas retidas'], ['geladeira', 'Geladeira', 'temperatura dos termolábeis']]], ['Estoque', [['estoque', 'Estoque', 'produtos, preço e promoção'], ['validade', 'Validade', 'vencidos e vencendo'], ['compras', 'Compras', 'entrada de nota']]], ['Clientes', [['clientes', 'Clientes', 'pontos e cadastro'], ['continuo', 'Uso contínuo', 'remédio acabando'], ['crediario', 'Crediário', 'quem compra para pagar depois'], ['servicos', 'Serviços', 'pressão, glicemia, injetáveis']]], ['Gestão', [['relatorios', 'Relatórios', 'vendas e margem'], ['equipe', 'Equipe', 'painel do dono'], ['ajustes', 'Ajustes', 'dados da farmácia']]]];
