const sugerido = (p) => { const m = db.markup[p.cat] ?? 50, s = Math.round(p.custo * (1 + m / 100) * 10) / 10 - 0.1; return Math.round((p.pmc ? Math.min(s, p.pmc) : s) * 100) / 100; };
const mesAtual = () => new Date().toISOString().slice(5, 7);
