  'gerar-pedidos': () => { const l = [...new Map([...db.prods.filter((p) => qtd(p) < p.min), ...db.faltas.filter((f) => f.st !== 'avisado').map((f) => db.prods.find((p) => sa(p.nome).includes(sa(f.prod).split(' ')[0]))).filter(Boolean)].map((p) => [p.id, p])).values()], por = {}; l.forEach((p) => { const [d0, v] = cotacao(p).sort((a, b) => a[1] - b[1])[0], q = Math.max(p.min * 3 - qtd(p), 1); (por[d0] ||= []).push({ p: p.id, q, v }); }); Object.entries(por).forEach(([dist, itens]) => db.pedidos.push({ id: uid(), dist, itens, total: Math.round(itens.reduce((s, i) => s + i.q * i.v, 0) * 100) / 100, dia: 0 })); salva(); tela(); aviso(`${Object.keys(por).length} pedido(s) enviados: ${Object.keys(por).join(', ')}.`); },
