  if (t.dataset.aj) { db[t.dataset.aj] = t.value; salva(); tela(); }
  if (t.dataset.limite) { const c = db.clientes.find((x) => x.id === t.dataset.limite), v = nv(t.value); if (!(v >= 0)) { aviso('Limite inválido.'); tela(); return; } if (v < c.deve) aviso(`Limite menor que a dívida (${R$(c.deve)}): novas compras no crediário ficam travadas.`); c.limite = v; salva(); tela(); }
